const icon=(name,sz='')=>`<svg class="ic ${sz==='sm'?'ic-sm':sz==='xs'?'ic-xs':sz==='lg'?'ic-lg':''}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.info}</svg>`;
const h=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const url=id=>`#/drug/${encodeURIComponent(id)}`;
const tidy=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const safeRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const safeWrite=(key,val)=>{try{localStorage.setItem(key,JSON.stringify(val))}catch{}};
const s={search:'',family:'Tutte',favesOnly:false,bookmarks:new Set(safeRead('pharma-favs',[])),theme:(()=>{const stored=safeRead('pharma-theme',null);return stored==='dark'||stored==='light'?stored:(window.matchMedia?.('(prefers-color-scheme: light)').matches?'light':'dark')})(),menu:false,overlay:false,globalQuery:'',labTarget:'ADRB1',agonist:55,antagonist:15,pk:{route:'oral',dose:100,half:8,vd:40,f:70,ka:1.2,interval:12,doses:4},caseChoice:null,caseOutcome:null,quizIdx:0,quizSelection:null,quizScore:0,quizCompleted:safeRead('pharma-quiz-completed',0),casesDone:new Set(safeRead('pharma-cases-done',[]))};
const route=()=>decodeURIComponent(location.hash.replace(/^#\/?/,''))||'home';
const routeParts=()=>route().split('/');
const nav=[['home','Panoramica','home'],['atlas','Farmaci','pill'],['receptors','Recettori','target'],['textbook','Teoria','books'],['quiz','Quiz','graduation']];
const baseRoute=()=>{const p=routeParts()[0];if(['drug','molecule','classes','class','compare','coverage','learning','learning-drug','dose','pk','evidence','sources','news'].includes(p))return 'atlas';if(['lab','cinema','receptors'].includes(p))return 'receptors';if(['case','cases','quiz'].includes(p))return 'quiz';return p};
function navItem([path,label,i]){return `<a class="navlink ${baseRoute()===path?'active':''}" href="#/${path}">${icon(i)}<span>${label}</span>${baseRoute()===path?'<span class="nav-pin"></span>':''}</a>`}
function layout(body){
 const p=routeParts();
 const title=p[0]==='drug'?drugById(p[1])?.name:p[0]==='case'?CASES.find(c=>c.id===p[1])?.title:nav.find(n=>n[0]===p[0])?.[1];
 const current=title||({molecule:'Scheda della molecola',classes:'Classi farmacologiche',class:'Teoria di classe',compare:'Confronto tra farmaci',coverage:'Copertura e fonti','learning-drug':'Percorso didattico'})[p[0]]||'Panoramica';
 const compact={home:'Panoramica',atlas:'Farmaci',receptors:'Recettori',textbook:'Teoria',quiz:'Quiz'};
 const topnav=nav.map(([path,label])=>`<a class="topnav-link ${baseRoute()===path?'active':''}" href="#/${path}" ${baseRoute()===path?'aria-current="page"':''}>${compact[path]||h(label)}</a>`).join('');
 const brand=`<a class="brand header-brand" href="#/home" aria-label="ELIX, torna alla panoramica"><span class="brand-mark"><img class="ex-brand-img" src="./assets/elix-pill-original.svg" alt=""/></span><span><span class="brand-name">ELIX</span><span class="brand-sub" style="display:block">Farmacologia &amp; Principi Attivi</span></span></a>`;
 const nextTheme=s.theme==='dark'?'chiaro':'scuro';
 const themeButton=`<button type="button" class="iconbtn theme-toggle" data-act="theme" aria-label="Passa al tema ${nextTheme}" aria-pressed="${s.theme==='light'}" title="Passa al tema ${nextTheme}">${icon(s.theme==='dark'?'sun':'moon')}<span class="theme-label">Tema ${nextTheme}</span></button>`;
 const drawer=`<aside class="sidebar ${s.menu?'mobile-open':''}" aria-label="Menu di navigazione mobile"><a class="brand" href="#/home"><span class="brand-mark"><img class="ex-brand-img" src="./assets/elix-pill-original.svg" alt=""/></span><span><span class="brand-name">ELIX</span><span class="brand-sub" style="display:block">Farmacologia &amp; Principi Attivi</span></span></a><div class="nav-caption">Esplora</div>${nav.map(navItem).join('')}<div class="side-spacer"></div><div class="side-info"><strong><span class="tiny-pill">ALPHA 0.9</span> Didattica sperimentale</strong><p>Un percorso essenziale: Farmaci, Recettori, Teoria e Quiz.</p></div><div class="side-end"><span>App made by Eliseo Peirano · 2026</span></div></aside>`;
 return `<div class="app-shell">${drawer}${s.menu?'<div class="mobile-shade" data-act="menu"></div>':''}<main class="main"><header class="topbar"><div class="header-primary"><button class="iconbtn mobile-toggle" data-act="menu" aria-label="Apri menu di navigazione">${icon('menu')}</button>${brand}</div><nav class="top-navigation" aria-label="Sezioni di ELIX">${topnav}</nav><div class="top-actions"><span class="header-credit">App made by Eliseo Peirano · 2026</span><button type="button" class="search-trigger" data-act="search-open" title="Cerca in ELIX (⌘K)" aria-label="Cerca farmaci, bersagli e casi clinici">${icon('search','sm')}</button>${themeButton}<span class="header-release">α 0.9</span></div></header><div class="context-bar"><div class="crumb"><span>ELIX Atlas</span>${icon('chevron','xs')}<strong>${h(current)}</strong></div><span class="context-version">Atlante internazionale · Fonti e copertura per scheda</span></div><div class="content">${body}</div><footer class="app-footer"><div class="footer-brand"><strong>ELIX</strong><span class="footer-dot"></span><span>App made by Eliseo Peirano · 2026</span></div><span class="footer-limit">Alpha 0.9 · Simulazioni didattiche · Copertura delle fonti dichiarata per scheda</span></footer></main></div>${s.overlay?searchOverlay():''}`;
}
const badge=(txt,cls='')=>`<span class="pill ${cls}">${h(txt)}</span>`;
const panel=(x,cls='')=>`<div class="panel ${cls}">${x}</div>`;
const heading=(eyebrow,title,lead,extra='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 class="section-title">${title}</h1>${lead?`<p class="section-lead">${lead}</p>`:''}</div>${extra?`<div class="header-actions">${extra}</div>`:''}</div>`;
function favButton(id){return `<button class="iconbtn" data-act="fav" data-id="${h(id)}" title="${s.bookmarks.has(id)?'Rimuovi dai preferiti':'Aggiungi ai preferiti'}" aria-label="Preferiti" style="color:${s.bookmarks.has(id)?'var(--accent)':'var(--muted)'}">${icon('bookmark')}</button>`}
function home(){const done=s.casesDone.size;return `
<div class="hero"><div class="hero-copy"><div class="over"><span class="dot"></span> La farmacologia, ripensata.</div><h1>Capire i farmaci.<br><em>Davvero.</em></h1><p>Dalla molecola al letto del paziente. Un atlante dove meccanismi, recettori, farmacocinetica e decisioni cliniche si incontrano.</p><div class="hero-actions"><a href="#/atlas" class="btn primary">Esplora l'atlante ${icon('arrow')}</a><a href="#/lab" class="btn ghost">Apri il laboratorio ${icon('atom')}</a></div></div><div class="hero-art"><div class="orb"></div><div class="molecule-label label-one">β1 · Gs</div><div class="molecule-label label-two">cAMP ↑</div><div class="molecule-label label-three">ADRB1</div><i class="hero-orb-node n1"></i><i class="hero-orb-node n2"></i><i class="hero-orb-node n3"></i></div></div>
<div class="stat-strip"><div class="stat-card"><div class="stat-head">${icon('pill')} Principi attivi</div><div class="number mono">${DRUGS.length}</div><div class="stat-foot">Percorsi didattici originali</div></div><div class="stat-card"><div class="stat-head">${icon('target')} Recettori attivi</div><div class="number mono">${TARGETS.length}</div><div class="stat-foot">Con laboratorio dinamico</div></div><div class="stat-card"><div class="stat-head">${icon('pulse')} Casi clinici</div><div class="number mono">${CASES.length}</div><div class="stat-foot">${done} completati su questo dispositivo</div></div><div class="stat-card"><div class="stat-head">${icon('graduation')} Quiz disponibili</div><div class="number mono">${elixStudio?.stats().questions??QUIZ.length}</div><div class="stat-foot">Per area, molecola e difficoltà</div></div></div>
<section class="ev-home-banner"><div><span class="eyebrow">Nuovo · Atlante internazionale</span><h2>Molecole, classi ed evidenze.</h2><p>4.225 record, strutture chimiche, stati Italia / UE / USA e rassegna settimanale.</p></div><div><a class="btn primary" href="#/atlas">Esplora le molecole →</a><a class="btn" href="#/classes">Confronta le classi</a><a class="btn" href="#/news">Novità e trial</a></div></section><div class="section-row"><h2>Il tuo laboratorio</h2><span class="pill green">${icon('spark','xs')} Interattivo</span></div><div class="feature-grid">
${feature('atom','Recettori in azione','Modifica agonista e antagonista. Osserva il segnale molecolare cambiare.','lab','purple')}
${feature('chart','Farmacocinetica visiva','Prova emivita, biodisponibilità, dose e intervallo.','pk','blue')}
${feature('pulse','Ospedale virtuale','Scegli un farmaco in un caso sintetico e scopri il perché.','cases','orange')}
</div>
<div class="section-row"><h2>Continua a esplorare</h2><a class="link-text" href="#/atlas">Tutti i farmaci ${icon('arrow','sm')}</a></div>
<div class="two-col">${panel(`<div class="panel-top"><span class="pill green">MECCANISMO DEL GIORNO</span>${icon('atom')}</div><h3 style="margin-top:20px;font-size:20px">Dal recettore β1 alla forza di contrazione</h3><p>Le catecolamine stimolano β1, che attiva Gs → adenilato ciclasi → cAMP → PKA. Qual è il collegamento con i flussi di Ca²⁺ nel cardiomiocita?</p><a class="link-text" href="#/lab">Sperimenta la cascata ${icon('arrow','sm')}</a>`)}${panel(`<div class="panel-top"><span class="pill amber">CASO CLINICO</span>${icon('pulse')}</div><h3 style="margin-top:20px;font-size:20px">Ipertensione e asma</h3><p>Stesso apparato cardiovascolare, ma recettori in organi diversi. Quale scelta evita di bloccare β2 nei bronchi?</p><a class="link-text" href="#/case/asma-beta">Apri il caso ${icon('arrow','sm')}</a>`)}</div>
<div class="callout" style="margin-top:20px">${icon('shield')}<div><strong>Protótipo didattico, non strumento clinico.</strong> I contenuti presenti sono esempi curati manualmente. La regolamentazione AIFA e le linee guida non sono sincronizzate. Nessuna terapia o dose va ricavata da questa app per pazienti reali.</div></div>`}
function feature(icn,t,desc,path,color=''){return `<a class="feature-card" href="#/${path}"><span class="feature-icon ${color}">${icon(icn)}</span><h3>${t}</h3><p>${desc}</p><span class="more">Inizia ora ${icon('arrow','xs')}</span></a>`}
function drugCard(d){return `<a class="drug-card" href="${url(d.id)}"><div class="drug-top"><span class="drug-symbol">${icon('pill')}</span><div><div class="drug-title">${h(d.name)}</div><div class="drug-sub">${h(d.family)} · ${h(d.subgroup)}</div></div><span style="margin-left:auto;color:var(--soft)">${icon('chevron','sm')}</span></div><div class="drug-details">${d.targets.slice(0,2).map(t=>badge(t,'green')).join('')}${badge(d.tag)}</div></a>`}
function filterDrugs(){return DRUGS.filter(d=>(s.family==='Tutte'||d.family===s.family)&&(!s.favesOnly||s.bookmarks.has(d.id))&&(!s.search||tidy(`${d.name} ${d.family} ${d.subgroup} ${d.targets.join(' ')} ${d.clinical}`).includes(tidy(s.search))))}
function atlasList(){const ds=filterDrugs();return `<div class="small muted" style="margin:0 0 13px">${ds.length} ${ds.length===1?'principio attivo':'principi attivi'} trovati</div><div class="atlas-list">${ds.map(drugCard).join('')}</div>${ds.length?'':`<div class="empty">${icon('search','lg')}<strong>Nessun farmaco trovato</strong><span>Prova un'altra classe o parola chiave.</span></div>`}`}
function atlas(){return `${heading('Atlante interconnesso','Esplora i principi attivi','Un catalogo didattico per meccanismo, famiglia e bersaglio. I prodotti commerciali, confezioni, RCP e regimi AIFA saranno collegati quando le fonti saranno integrate.',`${badge('Dati dimostrativi da revisionare','green')}`)}<div class="filter-row"><label class="field-wrap" style="flex:1;min-width:240px">${icon('search')}<input id="atlas-search" type="search" placeholder="Cerca un farmaco, una classe o un bersaglio…" value="${h(s.search)}" autocomplete="off"/></label><select id="family-select" class="select" aria-label="Filtra per classe"><option value="Tutte">Tutte le classi</option>${FAMILIES.sort((a,b)=>a.localeCompare(b,'it')).map(f=>`<option value="${h(f)}" ${s.family===f?'selected':''}>${h(f)}</option>`).join('')}</select><button class="btn ${s.favesOnly?'primary':''}" data-act="faves-filter">${icon('bookmark')} Preferiti</button></div><div id="atlas-results">${atlasList()}</div><div class="callout" style="margin-top:22px">${icon('info')}<div><strong>Distinzione fondamentale:</strong> un principio attivo non identifica un prodotto, una confezione o una specifica indicazione autorizzata. I campi di prescrivibilità e rimborsabilità devono essere associati ai corrispondenti record regolatori e alla versione della fonte.</div></div>`}
function drugDetail(id){const d=drugById(id);if(!d)return missing('Principio attivo non trovato','#/atlas');const cases=CASES.filter(c=>c.options.some(o=>o.id===id));const labTargets=d.targets.map(t=>targetById(t)).filter(Boolean);return `<div style="margin-bottom:23px"><a href="#/atlas" class="link-text">${icon('back','sm')} Torna all'atlante</a></div><div class="drug-detail-top"><span class="drug-detail-icon">${icon('pill','lg')}</span><div style="flex:1"><span class="eyebrow">Principio attivo</span><h1 class="section-title" style="margin:4px 0">${h(d.name)}</h1><span class="muted small">${h(d.family)} · ${h(d.subgroup)}</span></div>${favButton(id)}</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:25px">${badge(`ATC · ${d.atc}`,'green')}${badge(d.tag)}${badge('Record didattico • Non validato per prescrizione','amber')}</div><div class="detail-grid"><div>${panel(`<div class="detail-section"><h4>${icon('atom')} Meccanismo d'azione</h4><p>${h(d.mechanism)}</p></div><div class="detail-section"><h4>${icon('pulse')} Contesti d'impiego (esempi, non esaustivi)</h4><p>${h(d.clinical)}</p></div><div class="detail-section"><h4>${icon('alert')} Attenzioni farmacologiche</h4><p>${h(d.critical)}</p></div><div class="detail-section"><h4>${icon('chart')} Note ADME</h4><p>${h(d.pk)}</p></div>`)}<div class="notice" style="margin-top:15px">${icon('shield')}<div>Questa scheda riassume concetti didattici, non un RCP completo. Forme, posologie, popolazioni speciali, interazioni e controindicazioni devono essere consultate nella scheda ufficiale aggiornata del prodotto specifico.</div></div></div><div class="detail-side">${panel(`<h3>Bersagli molecolari</h3><p style="margin-top:3px">Dal farmaco al recettore, e viceversa.</p><div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:14px">${d.targets.map(t=>{const x=targetById(t);return x?`<a href="#/lab/${encodeURIComponent(t)}" class="link-chip">${icon('target','sm')} ${h(t)} ${icon('arrow','xs')}</a>`:`<span class="link-chip">${icon('target','sm')} ${h(t)} · scheda futura</span>`}).join('')}</div>`)}${panel(`<h3>Regolamentazione italiana</h3><p style="margin:3px 0 14px">Questi dati richiedono l'identificazione della specifica specialità/confezione.</p><div style="display:flex;flex-direction:column;gap:12px"><div class="panel-top"><span class="small muted">Classe di rimborsabilità</span>${badge('Da verificare','amber')}</div><div class="panel-top"><span class="small muted">Regime di fornitura</span>${badge('Da verificare','amber')}</div><div class="panel-top"><span class="small muted">Note AIFA / PT</span>${badge('Da verificare','amber')}</div><div class="panel-top"><span class="small muted">RCP / Foglio illustrativo</span>${badge('Non importati','amber')}</div></div><a target="_blank" rel="noopener noreferrer" href="https://medicinali.aifa.gov.it/" class="btn ghost" style="width:100%;margin-top:18px">Apri AIFA Medicinali ${icon('external','sm')}</a>`)}${cases.length?panel(`<h3>Presente nei casi clinici</h3>${cases.map(c=>`<a class="link-chip" style="margin:5px 4px 5px 0" href="#/case/${c.id}">${h(c.title)} ${icon('chevron','xs')}</a>`).join('')}`):''}${panel(`<h3>Collegamenti utili</h3><div style="display:flex;flex-direction:column;align-items:flex-start;gap:13px;margin-top:15px"><a class="link-text" href="#/pk">${icon('chart','sm')} Laboratorio farmacocinetico</a><a class="link-text" href="#/sources">${icon('books','sm')} Fonti ufficiali</a></div>`)}</div></div>`}
function doseFromSlider(n){return Math.pow(10,Number(n)/25-2)}
function emax(dose,ant){const a=doseFromSlider(dose);return 100*a/(.7*(1+Number(ant)/12)+a)}
function plotLine(vals,{w=520,height=235,left=45,right=17,top=16,bottom=35,max=100}={}){const W=w-left-right,H=height-top-bottom;return vals.map((v,i)=>`${i?'L':'M'}${(left+i/(vals.length-1)*W).toFixed(1)} ${(top+H-(v/max)*H).toFixed(1)}`).join(' ')}
function responseChart(){const w=520,ht=240,l=45,r=17,t=19,b=39,areaW=w-l-r,areaH=ht-t-b;const norm=Array.from({length:101},(_,i)=>emax(i,0)),treated=Array.from({length:101},(_,i)=>emax(i,s.antagonist));let pct=emax(s.agonist,s.antagonist),cx=l+s.agonist/100*areaW,cy=t+areaH*(1-pct/100);return `<div class="chart-wrap"><div class="chart-title">Curva concentrazione–risposta</div><div class="chart-sub">Modello illustrativo: agonista e antagonista competitivo, valori relativi</div><svg viewBox="0 0 ${w} ${ht}" role="img" aria-label="Grafico delle curve concentrazione-risposta relative"><defs><linearGradient id="acFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#6be4bd" stop-opacity=".14"/><stop offset="1" stop-color="#6be4bd" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(n=>`<line x1="${l}" y1="${t+areaH*(1-n/100)}" x2="${w-r}" y2="${t+areaH*(1-n/100)}" stroke="currentColor" opacity=".10"/><text x="${l-8}" y="${t+areaH*(1-n/100)+4}" fill="currentColor" opacity=".55" text-anchor="end" font-size="10">${n}</text>`).join('')}${['−2','−1','0','+1','+2'].map((v,i)=>`<text x="${l+i/4*areaW}" y="${ht-12}" fill="currentColor" opacity=".6" font-size="10" text-anchor="middle">${v}</text>`).join('')}<path d="${plotLine(norm)} L${w-r} ${t+areaH} L${l} ${t+areaH} Z" fill="url(#acFill)"/><path d="${plotLine(norm)}" fill="none" stroke="#83e8c6" stroke-width="3" stroke-linecap="round"/><path d="${plotLine(treated)}" fill="none" stroke="#b6a9ff" stroke-width="3" stroke-linecap="round"/><line x1="${cx}" x2="${cx}" y1="${t}" y2="${t+areaH}" stroke="currentColor" opacity=".24" stroke-dasharray="4 5"/><circle cx="${cx}" cy="${cy}" r="5.2" fill="#b6a9ff" stroke="#18212d" stroke-width="2"/><text x="${w-9}" y="${ht-12}" font-size="10" fill="currentColor" opacity=".5" text-anchor="end">log [agonista]</text><text x="14" y="12" font-size="10" fill="currentColor" opacity=".5">E (%)</text></svg><div class="chart-legend"><span><i class="legend-mark"></i>Agonista senza antagonista</span><span><i class="legend-mark purple"></i>Con antagonista</span></div></div>`}
function labLive(){const target=targetById(s.labTarget)||TARGETS[0];const pct=Math.round(emax(s.agonist,s.antagonist));const tone=pct>65?'on':pct>20?'mid':'';return `<div class="lab-membrane"><span class="membrane-label ext">Spazio extracellulare</span><div class="membrane-line"></div><span class="ligand" style="opacity:${.22+s.agonist*.0075}"></span>${s.antagonist>2?`<span class="antagonist-dot" style="opacity:${.3+s.antagonist*.007}"></span>`:''}<div class="receptor ${pct<30?'inhibited':''}">${target.id==='AGTR1'?'AT1':target.id==='ADRB2'?'β2':'β1'}</div><span class="signal-g"><span style="opacity:${.2+pct/125}"></span> ${target.kind.includes('Gq')?'Gq/11':'Gs'} · ${pct}%</span><span class="membrane-label int">Citoplasma</span></div><div class="cascade">${target.downstream.map((step,i)=>`<span class="cascade-step ${tone}" title="Segnale qualitativo: ${pct}%">${h(step)}</span>`).join('<span class="dim">›</span>')}</div><div style="margin:24px 0 12px" class="panel-top"><div><strong style="font-size:13px">Segnalazione normalizzata</strong><div class="muted tiny" style="margin-top:5px">Valore matematico relativo, non misurazione reale</div></div><span class="pill green">${pct}%</span></div><div style="height:9px;border-radius:20px;background:var(--panel3);overflow:hidden"><div style="height:100%;width:${pct}%;background:linear-gradient(90deg,var(--accent),var(--purple));border-radius:20px;transition:width .15s"></div></div><div style="margin-top:24px">${responseChart()}</div><div class="inline-metric"><div><b>${pct}%</b><span>Risposta relativa</span></div><div><b>${Math.round(emax(s.agonist,0))}%</b><span>Senza antagonista</span></div><div><b>${Math.max(0,Math.round(emax(s.agonist,0)-pct))} pp</b><span>Attenuazione</span></div></div>`}
function lab(){const target=targetById(s.labTarget)||TARGETS[0];const connected=DRUGS.filter(d=>d.targets.includes(target.id));return `${heading('Laboratorio molecolare','Tocca il recettore. Cambia il segnale.','Modifica le concentrazioni relative e osserva una simulazione matematica di antagonismo competitivo. Il modello è intenzionalmente semplificato e non rappresenta parametri sperimentali di un farmaco.',`${badge('Modello teorico','purple')}`)}<div class="stepper">${TARGETS.map(x=>`<button class="step-tab ${x.id===target.id?'active':''}" data-act="lab-target" data-id="${x.id}">${x.id==='ADRB1'?'β1-adrenergico':x.id==='ADRB2'?'β2-adrenergico':'AT1'}</button>`).join('')}</div><div class="lab-layout"><div>${panel(`<div class="panel-top"><span class="pill green">${h(target.kind)}</span>${icon('sliders')}</div><h3 style="font-size:20px;margin:17px 0 6px">${h(target.name)}</h3><p style="margin:0">${h(target.organ)}</p><div class="control-line"><div class="control-head"><strong>Agonista · concentrazione relativa</strong><output id="agonist-value">${s.agonist}/100</output></div><input aria-label="Concentrazione agonista" class="range" type="range" min="0" max="100" step="1" value="${s.agonist}" data-range="agonist"/><div class="range-labels"><span>Molto bassa</span><span>Molto alta</span></div></div><div class="control-line"><div class="control-head"><strong>Antagonista · concentrazione relativa</strong><output id="antagonist-value">${s.antagonist}/100</output></div><input aria-label="Concentrazione antagonista" class="range" type="range" min="0" max="100" step="1" value="${s.antagonist}" data-range="antagonist"/><div class="range-labels"><span>Assente</span><span>Elevata</span></div></div><div style="display:flex;gap:8px;margin-top:22px"><button class="btn" data-act="lab-reset">${icon('refresh','sm')} Reimposta</button></div><div class="detail-section" style="margin-top:18px"><h4>${icon('info')} Che cosa stai osservando?</h4><p style="font-size:12px">${h(target.description)}</p></div><div class="safe-note" style="margin-top:15px">Agonista modello: ${h(target.agonist)}. Antagonista modello: ${h(target.antagonist)}. Le curve non derivano da valori sperimentali Ki/EC50 e non stimano effetti clinici.</div>`)}${panel(`<h3>Farmaci e bersagli collegati</h3><p>Apri le schede del catalogo che interagiscono con questo target.</p><div style="display:flex;flex-wrap:wrap;gap:7px">${connected.map(d=>`<a class="link-chip" href="${url(d.id)}">${h(d.name)} ${icon('chevron','xs')}</a>`).join('')}</div>`, 'detail-side') }</div><div class="panel" id="lab-live">${labLive()}</div></div><div class="callout" style="margin-top:18px">${icon('flask')}<div>Il modello Emax usato qui è <b>E = 100 × [A] / (EC₅₀ × (1 + [B]/Kᵢ) + [A])</b> con parametri relativi arbitrari. Mostra il principio dello spostamento della curva per antagonismo competitivo, non la risposta effettiva del paziente.</div></div>`}
function pkConcentration(t){const p=s.pk,ke=Math.log(2)/p.half,ka=p.ka,F=p.route==='oral'?p.f/100:1,V=p.vd;let res=0;for(let n=0;n<p.doses;n++){let dt=t-n*p.interval;if(dt<0)continue;if(p.route==='iv')res+=p.dose/V*Math.exp(-ke*dt);else if(Math.abs(ka-ke)<.00001)res+=(F*p.dose/V)*ka*dt*Math.exp(-ke*dt);else res+=(F*p.dose/V)*(ka/(ka-ke))*(Math.exp(-ke*dt)-Math.exp(-ka*dt));}return Math.max(0,res)}
function pkStats(){const data=Array.from({length:385},(_,i)=>({t:i/4,c:pkConcentration(i/4)}));const max=data.reduce((best,p)=>p.c>best.c?p:best,data[0]);let auc=0;for(let i=1;i<data.length;i++)auc+=.25*(data[i].c+data[i-1].c)/2;return {data,max,auc,c24:pkConcentration(24)}}
function pkChart(){const {data,max}=pkStats(),w=700,ht=315,l=55,r=17,top=24,b=43,W=w-l-r,H=ht-top-b,maxY=Math.max(1,Math.ceil(max.c*1.2*10)/10);const xy=(d)=>[l+(d.t/96)*W,top+H-(d.c/maxY)*H];const path=data.map((d,i)=>`${i?'L':'M'}${xy(d)[0].toFixed(1)} ${xy(d)[1].toFixed(1)}`).join(' ');return `<div class="chart-wrap"><div class="chart-title">Concentrazione plasmatica nel tempo</div><div class="chart-sub">Modello monocompartimentale ipotetico · ${s.pk.route==='oral'?'assorbimento orale di primo ordine':'boli endovenosi'} · dosi ripetute</div><svg viewBox="0 0 ${w} ${ht}" role="img" aria-label="Grafico teorico concentrazione-tempo, da zero a 96 ore"><defs><linearGradient id="pkFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#86e7c3" stop-opacity=".25"/><stop offset="1" stop-color="#86e7c3" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="${l}" x2="${w-r}" y1="${top+H*(1-v)}" y2="${top+H*(1-v)}" stroke="currentColor" opacity=".11"/><text x="${l-8}" y="${top+H*(1-v)+4}" fill="currentColor" text-anchor="end" font-size="10" opacity=".6">${(maxY*v).toFixed(1)}</text>`).join('')}${[0,12,24,36,48,60,72,84,96].map(v=>`<text x="${l+v/96*W}" y="${ht-18}" fill="currentColor" text-anchor="middle" font-size="10" opacity=".6">${v}</text>`).join('')}${Array.from({length:s.pk.doses},(_,i)=>i*s.pk.interval).filter(x=>x<=96).map(t=>`<line x1="${l+t/96*W}" x2="${l+t/96*W}" y1="${top}" y2="${top+H}" stroke="currentColor" opacity=".17" stroke-dasharray="3 5"/>`).join('')}<path d="${path} L${w-r} ${top+H} L${l} ${top+H} Z" fill="url(#pkFill)"/><path d="${path}" fill="none" stroke="#83e8c6" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/><circle cx="${xy(max)[0]}" cy="${xy(max)[1]}" r="5" fill="#83e8c6" stroke="#1f2b32" stroke-width="2"/><text x="${w-8}" y="${ht-5}" fill="currentColor" opacity=".55" font-size="10" text-anchor="end">Tempo (ore)</text><text x="7" y="13" fill="currentColor" opacity=".55" font-size="10">mg/L</text></svg><div class="chart-legend"><span><i class="legend-mark"></i>Concentrazione teorica</span><span>│ = somministrazione modellizzata</span></div></div>`}
function pkLive(){let {max,auc,c24}=pkStats();return `${pkChart()}<div class="pk-results"><div><small>Cmax teorica</small><b class="mono">${max.c.toFixed(2)}</b><small>mg/L</small></div><div><small>Tmax dall'inizio</small><b class="mono">${max.t.toFixed(1)}</b><small>ore</small></div><div><small>AUC₀₋₉₆</small><b class="mono">${auc.toFixed(1)}</b><small>mg·h/L</small></div><div><small>C(24h)</small><b class="mono">${c24.toFixed(2)}</b><small>mg/L</small></div><div><small>Costante di eliminazione</small><b class="mono">${(Math.log(2)/s.pk.half).toFixed(3)}</b><small>h⁻¹</small></div><div><small>Tempo di dimezzamento</small><b class="mono">${s.pk.half}</b><small>ore</small></div></div>`}
function pkSlider(label,key,min,max,step,unit){return `<div class="pk-control"><label for="pk-${key}"><span>${label}</span><b id="pkl-${key}">${s.pk[key]} ${unit}</b></label><input class="range" id="pk-${key}" data-pk="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${s.pk[key]}"></div>`}
function pk(){return `${heading('Farmacocinetica sperimentale','ADME, ma con le mani.','Esplora come cambiano le concentrazioni in un modello teorico a un compartimento. I parametri sono ipotetici, non quelli di alcun medicinale in commercio.',`${badge('Simulatore matematico','purple')}`)}<div class="pk-grid"><div>${panel(`<div class="panel-top"><h3>Imposta lo scenario</h3>${icon('sliders')}</div><div class="pk-control"><label for="pk-route"><span>Via di somministrazione</span></label><select id="pk-route"><option value="oral" ${s.pk.route==='oral'?'selected':''}>Orale · assorbimento di 1° ordine</option><option value="iv" ${s.pk.route==='iv'?'selected':''}>Endovenosa · bolo</option></select></div>${pkSlider('Dose per somministrazione','dose',10,500,10,'mg')}${pkSlider('Emivita di eliminazione','half',1,30,1,'h')}${pkSlider('Volume di distribuzione','vd',5,100,5,'L')}${s.pk.route==='oral'?pkSlider('Biodisponibilità','f',10,100,5,'%')+pkSlider('Costante di assorbimento ka','ka',0.2,3,.2,'h⁻¹'):''}${pkSlider('Intervallo tra dosi','interval',6,24,2,'h')}${pkSlider('Numero di dosi','doses',1,6,1,'')}<button class="btn" data-act="pk-reset" style="margin-top:18px">${icon('refresh','sm')} Valori iniziali</button>`)}<div class="safe-note" style="margin-top:14px">F è applicata solo alla via orale. Assunti: distribuzione istantanea in un compartimento, eliminazione lineare, dose costante, nessuna variabilità biologica.</div></div><div class="panel" id="pk-live">${pkLive()}</div></div><div class="callout" style="margin-top:18px">${icon('info')}<div>Il grafico mostra un modello di Bateman per l'assorbimento orale e decadimento esponenziale per boli EV. Non usa dati sperimentali, non calcola dosaggi clinici e non sostituisce il monitoraggio terapeutico.</div></div>`}
function cases(){return `${heading('Ospedale virtuale','Impara a decidere.','${CASES.length} casi sintetici in cui devi scegliere o riconoscere un farmaco, prevedere i rischi e collegare la scelta al suo meccanismo. Non rappresentano decisioni da applicare a persone reali.',`${badge(`${s.casesDone.size}/${CASES.length} completati`,'green')}`)}<div class="case-list">${CASES.map(c=>`<a class="case-card" href="#/case/${c.id}"><div class="panel-top"><span class="pill ${s.casesDone.has(c.id)?'green':'purple'}">${s.casesDone.has(c.id)?icon('check','xs')+' Completato':h(c.label)}</span><span class="muted tiny">${icon('clock','xs')} ${h(c.time)}</span></div><h3>${h(c.title)}</h3><p>${h(c.area)} · ${h(c.patient)}<br>${h(c.history.substring(0,100))}…</p><div class="case-foot"><span class="pill">${h(c.difficulty)}</span><span class="link-text">Apri il caso ${icon('arrow','sm')}</span></div></a>`).join('')}</div><div class="callout" style="margin-top:20px">${icon('shield')}<div>Le osservazioni del simulatore sono <strong>qualitative, didattiche e preimpostate</strong>: non sono pronostici, non generano un dosaggio e non sostituiscono la consultazione delle linee guida cliniche attuali.</div></div>`}
function caseDetail(id){const c=CASES.find(x=>x.id===id);if(!c)return missing('Caso non trovato','#/cases');const sel=c.options[s.caseChoice??-1];return `<div style="margin-bottom:21px"><a href="#/cases" class="link-text">${icon('back','sm')} Tutti i casi</a></div><div class="page-heading"><div><div class="eyebrow">${h(c.label)} · ${h(c.area)}</div><h1 class="section-title">${h(c.title)}</h1><p class="section-lead">${h(c.patient)} · ${h(c.difficulty)} · ${h(c.time)} di lettura</p></div><div class="header-actions">${badge('Paziente sintetico','purple')}</div></div><div class="case-layout"><div><div class="case-profile"><span class="patient-avatar">${icon('user','lg')}</span><div><h3>Quadro clinico iniziale</h3><p>${h(c.history)}</p></div></div><div class="vitals">${c.vitals.map(x=>`<div class="vital"><small>${h(x.label)}</small><b class="mono">${h(x.value)}</b><em>${h(x.unit)}</em></div>`).join('')}</div>${panel(`<div class="eyebrow">Prendi una decisione</div><h3 style="font-size:18px;line-height:1.5;margin:12px 0 17px">${h(c.question)}</h3>${c.options.map((o,i)=>`<button class="case-choice ${s.caseChoice===i?'selected':''}" data-act="case-select" data-index="${i}" ${s.caseOutcome?'disabled':''}><span>${h(o.drug)}</span><span class="radio-dot"></span></button>`).join('')}<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:19px;flex-wrap:wrap"><span class="muted tiny">Le opzioni servono a esplorare il meccanismo.</span><button class="btn primary" data-act="case-submit" ${s.caseChoice===null||s.caseOutcome?'disabled':''}>${icon('pulse','sm')} ${c.id==='asma-beta'?'Somministra (simulazione)':'Valuta la scelta'}</button></div>${s.caseOutcome?`<div class="outcome ${sel.correct?'good':'bad'}" style="margin-top:20px"><div class="outcome-head">${icon(sel.correct?'check':'alert')} ${sel.correct?'Risposta identificata':'Approfondisci questa scelta'}</div><div>${h(sel.effect)} — ${h(sel.response)}</div><p><strong>Meccanismo:</strong> ${h(sel.why)}</p><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:15px"><a href="${url(sel.id)}" class="btn smallbtn">Apri ${h(drugById(sel.id)?.name||'la scheda')} ${icon('arrow','xs')}</a><button class="btn smallbtn" data-act="case-again">${icon('refresh','xs')} Riprova</button></div></div>`:''}`)}${s.caseOutcome?panel(`<h3>Il collegamento da ricordare</h3><p>${h(c.learn)}</p><a class="link-text" href="#/${targetById(c.target)?'lab':'receptors'}/${encodeURIComponent(c.target)}">${icon('target','sm')} ${targetById(c.target)?'Apri il laboratorio del recettore':'Apri i recettori correlati'} ${icon('arrow','xs')}</a>`, 'case-learning'):''}</div><div>${panel(`<h3>Timeline della visita</h3><div class="case-timeline"><div><b>01 · Accoglienza</b> Anamnesi sintetica e primi parametri</div><div><b>02 · Decisione terapeutica</b> Analisi del farmaco e del bersaglio molecolare</div><div><b>03 · Risposta didattica</b> ${s.caseOutcome?'Scenario interpretato e spiegazione disponibile':'In attesa della scelta dello studente'}</div></div>`)}${panel(`<h3>Farmaci in questa situazione</h3><p>Approfondisci gli agenti disponibili prima di rispondere.</p><div style="display:flex;gap:7px;flex-wrap:wrap">${[...new Set(c.options.map(x=>x.id))].map(x=>`<a class="link-chip" href="${url(x)}">${h(drugById(x)?.name||x)} ${icon('chevron','xs')}</a>`).join('')}</div>`)}${panel(`<h3>Nota per la sicurezza</h3><div class="safe-note" style="margin-top:12px">Il caso è un esercizio con informazioni intenzionalmente incomplete. Il suo feedback valuta soltanto la domanda proposta, non la gestione clinica complessiva di una persona.</div>`)}</div></div>`}
function quiz(){if(s.quizIdx>=QUIZ.length){const pct=Math.round(s.quizScore/QUIZ.length*100);return `<div class="quiz-shell">${heading('Allenamento completato','Ottimo, sessione conclusa.','Hai terminato i quesiti di farmacologia generale e clinica del prototipo.')}<div class="panel" style="text-align:center"><span class="pill green">${icon('trophy','xs')} Risultato finale</span><div class="result-circle"><div><strong>${pct}%</strong><br><small>corrette</small></div></div><h2>${s.quizScore} risposte esatte su ${QUIZ.length}</h2><p>Ripeti il quiz oppure esplora i farmaci e le vie di segnalazione.</p><div style="display:flex;justify-content:center;gap:10px;margin:23px 0 2px"><button class="btn primary" data-act="quiz-reset">${icon('refresh','sm')} Riprova</button><a href="#/atlas" class="btn">Esplora l'atlante ${icon('arrow','sm')}</a></div></div></div>`}const q=QUIZ[s.quizIdx];return `<div class="quiz-shell">${heading('Allenamento attivo','Farmacologia ragionata.','Ogni domanda è collegata al principio attivo e al meccanismo che devi comprendere.',`${badge(`${s.quizIdx+1} di ${QUIZ.length}`,'green')}`)}<div class="progress-rail"><div class="progress-fill" style="width:${s.quizIdx/QUIZ.length*100}%"></div></div><div class="panel"><div class="panel-top"><span class="pill purple">Domanda ${s.quizIdx+1}</span><span class="muted tiny">${icon('target','xs')} Scelta singola</span></div><h2 style="font-size:22px;line-height:1.45;letter-spacing:-.026em;margin:21px 0 20px">${h(q.q)}</h2>${q.answers.map((a,i)=>`<button data-act="quiz-answer" data-index="${i}" class="answer ${s.quizSelection!==null?(i===q.correct?'correct':i===s.quizSelection?'wrong':''):''}" ${s.quizSelection!==null?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${h(a)}</span>${s.quizSelection!==null&&i===q.correct?`<span class="answer-right">${icon('check')}</span>`:''}</button>`).join('')}${s.quizSelection!==null?`<div class="outcome ${s.quizSelection===q.correct?'good':'bad'}" style="margin-top:20px"><div class="outcome-head">${icon(s.quizSelection===q.correct?'check':'info')} ${s.quizSelection===q.correct?'Esatto!':'Non proprio: ecco il perché'}</div><p style="margin-top:0">${h(q.why)}</p><a href="${url(q.drug)}" class="link-text" style="margin-top:10px">Collega alla scheda ${h(drugById(q.drug)?.name)} ${icon('arrow','xs')}</a></div><div style="display:flex;justify-content:flex-end;margin-top:19px"><button class="btn primary" data-act="quiz-next">${s.quizIdx===QUIZ.length-1?'Vedi risultato':'Prossima domanda'} ${icon('arrow','sm')}</button></div>`:''}</div><p class="footnote">Domande dimostrative non validate come test universitario ufficiale. Il progresso della sessione resta sul dispositivo.</p></div>`}
function sources(){return `${heading('Trasparenza e aggiornamenti','Le fonti prima di tutto.','L’app mostra dove cercare i dati autorevoli. I contenuti regolatori, i testi RCP e le linee guida non sono ancora importati o sincronizzati automaticamente.',`${badge('Nessuna connessione API live','amber')}`)}<div class="data-grid" style="margin-bottom:27px">${panel(`${icon('database')}<br><strong>Catalogo locale</strong><p>${DRUGS.length} principi attivi didattici, descrizioni redatte manualmente.</p>${badge('Demo','green')}`)}${panel(`${icon('lock')}<br><strong>Dati autorizzativi</strong><p>Rimborsabilità, ricette, note, formulazioni e AIC da associare alle fonti ufficiali.</p>${badge('Non sincronizzato','amber')}`)}${panel(`${icon('layers')}<br><strong>Pathway dinamici</strong><p>Tre modelli concettuali integrati, senza estrazione automatica da database esterni.</p>${badge('Semplificato','purple')}`)}</div><div class="section-row"><h2>Fonti istituzionali e scientifiche</h2>${badge('Collegamenti verificati')}</div><div class="source-grid">${SOURCES.map(x=>`<div class="source-card"><div class="panel-top"><span class="pill">${h(x.kind)}</span>${icon('external','sm')}</div><h3>${h(x.name)}</h3><span class="source-owner">${h(x.owner)}</span><p>${h(x.desc)}</p><div class="source-foot"><a class="link-text" target="_blank" rel="noopener noreferrer" href="${h(x.url)}">Apri la fonte ${icon('arrow','sm')}</a></div><div class="source-status">${icon('info','xs')} ${h(x.status)}</div></div>`).join('')}</div><div class="section-row"><h2>Come sarà strutturata la provenienza dei dati</h2></div>${panel(`<div class="detail-section"><h4>${icon('database')} Identità univoche</h4><p>Principio attivo → bersaglio → patologia; separatamente medicinale → AIC → confezione → regime di fornitura → rimborsabilità → indicazione → RCP.</p></div><div class="detail-section"><h4>${icon('clock')} Versioni e date di validità</h4><p>Ogni record normativo dovrà conservare ente, link ufficiale, identificatore, data di importazione e validità. Un cambiamento normativo non deve modificare silenziosamente i dati storici.</p></div><div class="detail-section"><h4>${icon('shield')} Sicurezza e licenze</h4><p>Niente riuso di dati commerciali senza autorizzazione. Nessuna raccomandazione prescrittiva rivolta a pazienti reali. Prima dell'uso professionale serviranno verifica specialistica e valutazione normativa.</p></div>`)}<div class="callout" style="margin-top:19px">${icon('info')}<div><strong>AIFA, EMA e FDA non sono intercambiabili:</strong> EMA espone soprattutto i medicinali valutati centralmente. Per stato di commercio, ricetta e rimborsabilità in Italia bisogna risalire al record nazionale pertinente.</div></div>`}
function missing(msg,to){return `<div class="empty">${icon('alert','lg')}<strong>${h(msg)}</strong><a href="${to}" class="btn">Torna indietro ${icon('back','sm')}</a></div>`}
function searchMatches(){const q=tidy(s.globalQuery.trim());if(!q)return [...DRUGS.slice(0,5).map(d=>({type:'Farmaco',name:d.name,sub:d.family,link:url(d.id),ic:'pill'})),...TARGETS.slice(0,1).map(t=>({type:'Recettore',name:t.name,sub:t.kind,link:`#/lab/${t.id}`,ic:'atom'}))];return [...DRUGS.filter(d=>tidy(d.name+' '+d.family+' '+d.subgroup+' '+d.targets.join(' ')).includes(q)).map(d=>({type:'Farmaco',name:d.name,sub:d.family,link:url(d.id),ic:'pill'})),...TARGETS.filter(t=>tidy(t.name+' '+t.id+' '+t.organ).includes(q)).map(t=>({type:'Recettore',name:t.name,sub:t.kind,link:`#/lab/${t.id}`,ic:'atom'})),...CASES.filter(c=>tidy(c.title+' '+c.area+' '+c.history).includes(q)).map(c=>({type:'Caso clinico',name:c.title,sub:c.area,link:`#/case/${c.id}`,ic:'pulse'}))].slice(0,12)}
function globalResults(){const core=searchMatches();const expanded=evidenceAtlas?.search(s.globalQuery)||[];const results=expanded.length?[...expanded,...core.filter(x=>x.type!=='Farmaco')].slice(0,15):core;return results.length?results.map(x=>`<a class="search-item" href="${x.link}"><span class="search-icon">${icon(x.ic,'sm')}</span><span><strong>${h(x.name)}</strong><small>${h(x.type)} · ${h(x.sub)}</small></span>${icon('chevron','sm')}</a>`).join(''):`<div class="empty" style="min-height:130px">${icon('search')} Nessun risultato. Prova un sinonimo o apri il catalogo internazionale.</div>`}
function searchOverlay(){return `<div class="search-overlay" data-act="search-close" id="search-overlay"><div class="search-dialog"><div class="search-dialog-top">${icon('search')}<input id="global-search" type="search" autocomplete="off" autofocus placeholder="Farmaci, recettori, meccanismi, casi…" value="${h(s.globalQuery)}" aria-label="Ricerca globale"/><button class="iconbtn" data-act="search-close" aria-label="Chiudi ricerca">${icon('close')}</button></div><div class="search-dialog-results" id="global-results">${globalResults()}</div><div class="search-dialog-footer"><span>Catalogo internazionale · Recettori · Casi</span><span>ESC per chiudere</span></div></div></div>`}
function render(){document.body.setAttribute('data-theme',s.theme);const metaTheme=document.querySelector('meta[name="theme-color"]');if(metaTheme)metaTheme.content=s.theme==='dark'?'#182230':'#edf2ee';let [p,id]=routeParts();if(p==='lab'&&id&&targetById(id))s.labTarget=id;let content=elixStudio?.route(p,id)||receptorAtlas?.route(p,id)||evidenceAtlas?.route(p,id)||({home,atlas,lab,pk,cases,quiz,sources,learning:atlas})[p]?.()||(['drug','learning-drug'].includes(p)?drugDetail(id):p==='case'?caseDetail(id):missing('Pagina non trovata','#/home'));document.getElementById('app').innerHTML=layout(content);if(s.overlay){const el=document.getElementById('global-search');el?.focus();el?.setSelectionRange?.(el.value.length,el.value.length)}}
function closeSearch(){if(s.overlay){s.overlay=false;s.globalQuery='';render()}}
function resetPk(){s.pk={route:'oral',dose:100,half:8,vd:40,f:70,ka:1.2,interval:12,doses:4}}
function action(act,el){switch(act){
case 'theme':s.theme=s.theme==='dark'?'light':'dark';safeWrite('pharma-theme',s.theme);render();break;
case 'menu':s.menu=!s.menu;render();break;
case 'search-open':s.overlay=true;render();break;
case 'search-close':closeSearch();break;
case 'fav':{const id=el.dataset.id;if(s.bookmarks.has(id))s.bookmarks.delete(id);else s.bookmarks.add(id);safeWrite('pharma-favs',[...s.bookmarks]);render();break}
case 'faves-filter':s.favesOnly=!s.favesOnly;render();break;
case 'lab-target':s.labTarget=el.dataset.id;s.agonist=55;s.antagonist=15;location.hash=`#/lab/${s.labTarget}`;render();break;
case 'lab-reset':s.agonist=55;s.antagonist=15;render();break;
case 'pk-reset':resetPk();render();break;
case 'case-select':if(!s.caseOutcome){s.caseChoice=Number(el.dataset.index);render()}break;
case 'case-submit':{let c=CASES.find(c=>c.id===routeParts()[1]);if(!c||s.caseChoice===null||!c.options[s.caseChoice])break;s.caseOutcome=true;s.casesDone.add(c.id);safeWrite('pharma-cases-done',[...s.casesDone]);render();break}
case 'case-again':s.caseChoice=null;s.caseOutcome=null;render();break;
case 'quiz-answer':{if(s.quizSelection!==null)break;const idx=Number(el.dataset.index);s.quizSelection=idx;if(idx===QUIZ[s.quizIdx].correct)s.quizScore++;render();break}
case 'quiz-next':{if(s.quizSelection===null)break;s.quizIdx++;s.quizSelection=null;if(s.quizIdx===QUIZ.length){s.quizCompleted++;safeWrite('pharma-quiz-completed',s.quizCompleted)}render();break}
case 'quiz-reset':s.quizIdx=0;s.quizSelection=null;s.quizScore=0;render();break;
}}
document.addEventListener('click',e=>{const hit=e.target.closest('[data-act]');if(hit){if(hit.id==='search-overlay'&&e.target!==hit)return;e.preventDefault();action(hit.dataset.act,hit)}const link=e.target.closest('a[href^="#/"]');if(link&&s.menu){s.menu=false;if(route()===link.getAttribute('href').replace('#/',''))render()}});
document.addEventListener('input',e=>{let x=e.target;
if(x.id==='atlas-search'){s.search=x.value;const area=document.getElementById('atlas-results');if(area)area.innerHTML=atlasList()}
if(x.id==='global-search'){s.globalQuery=x.value;const area=document.getElementById('global-results');if(area)area.innerHTML=globalResults()}
if(x.dataset.range){s[x.dataset.range]=Number(x.value);document.getElementById(`${x.dataset.range}-value`).textContent=`${x.value}/100`;const area=document.getElementById('lab-live');if(area)area.innerHTML=labLive()}
if(x.dataset.pk){s.pk[x.dataset.pk]=Number(x.value);const lbl=document.getElementById('pkl-'+x.dataset.pk);if(lbl){let u={dose:'mg',half:'h',vd:'L',f:'%',ka:'h⁻¹',interval:'h',doses:''}[x.dataset.pk];lbl.textContent=`${x.value} ${u}`}const area=document.getElementById('pk-live');if(area)area.innerHTML=pkLive()}
});
document.addEventListener('change',e=>{const x=e.target;if(x.id==='family-select'){s.family=x.value;render()}if(x.id==='pk-route'){s.pk.route=x.value;render()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();s.overlay=!s.overlay;render()}if(e.key==='Escape'&&s.overlay){closeSearch()}});
window.addEventListener('hashchange',()=>{s.menu=false;s.overlay=false;s.globalQuery='';s.caseChoice=null;s.caseOutcome=null;window.scrollTo({top:0,behavior:'instant'});render()});
