  iupar:'https://www.guidetopharmacology.org/',
  betaReview:'https://pmc.ncbi.nlm.nih.gov/articles/PMC4718210/',
  propranololUS:'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1791ef4d-b609-41c8-b4ef-15bff752ddd7',
  aifa:'https://medicinali.aifa.gov.it/',
  emaPMS:'https://plm-portal.ema.europa.eu/Guidance/article/KA-02917/en-us',
  reactomeLicense:'https://reactome.org/license',
